#include "box3d/box3d.h"
#include <cassert>
#include <cstdio>
int main(int argc,char** argv){assert(argc==2);auto recording=b3LoadRecordingFromFile(argv[1]);assert(recording);const int bytes=b3Recording_GetSize(recording);auto player=b3CreatePlayer(b3Recording_GetData(recording),bytes,1);assert(player);auto info=b3RecPlayer_GetInfo(player);assert(info.frameCount==64);unsigned kindCount[7]={},hitCount[7]={},missCount[7]={},duplicateKeyFrames=0,untagged=0;int minBodies=100,maxBodies=0,spawnVisibleFrames=0,removedOrdinalFrames=0;unsigned contacts=0;
while(b3RecPlayer_StepFrame(player)){auto replayWorld=b3RecPlayer_GetWorldId(player);auto counters=b3World_GetCounters(replayWorld);if(counters.bodyCount<minBodies)minBodies=counters.bodyCount;if(counters.bodyCount>maxBodies)maxBodies=counters.bodyCount;if(counters.bodyCount==6)++spawnVisibleFrames;if(b3RecPlayer_GetBodyCount(player)==6&&B3_IS_NULL(b3RecPlayer_GetBodyId(player,5)))++removedOrdinalFrames;uint64_t closestKey=0;int repeats=0;for(int q=0;q<b3RecPlayer_GetFrameQueryCount(player);++q){auto query=b3RecPlayer_GetFrameQuery(player,q);assert(query.type>=0&&query.type<7);++kindCount[query.type];if(query.hitCount)++hitCount[query.type];else ++missCount[query.type];if(query.key==0)++untagged;if(query.id==104){if(!closestKey)closestKey=query.key;else if(query.key==closestKey)++repeats;}}if(repeats)++duplicateKeyFrames;auto rest=b3RecPlayer_GetBodyId(player,1);contacts+=b3Body_GetContactCapacity(rest);}
assert(!b3RecPlayer_HasDiverged(player));assert(minBodies==5&&maxBodies==6&&spawnVisibleFrames==8&&removedOrdinalFrames==48);assert(duplicateKeyFrames==64&&untagged==64&&contacts>0);for(int i=0;i<7;++i){assert(kindCount[i]>=64&&missCount[i]>0);if(i!=b3_recQueryCastMover)assert(hitCount[i]>0);}std::printf("{\"status\":\"EXISTING_REAL_BOX3D_RECORDING_COVERAGE_EXTRACTED\",\"frames\":64,\"bytes\":%d,\"min_bodies\":%d,\"max_bodies\":%d,\"spawn_visible_frames\":%d,\"removed_ordinal_frames\":%d,\"same_key_instance_frames\":%u,\"untagged_queries\":%u,\"contact_capacity_sum\":%u,\"query_kinds\":[",bytes,minBodies,maxBodies,spawnVisibleFrames,removedOrdinalFrames,duplicateKeyFrames,untagged,contacts);for(int i=0;i<7;++i){if(i)std::putchar(',');std::printf("{\"kind\":%d,\"queries\":%u,\"positive\":%u,\"miss\":%u}",i,kindCount[i],hitCount[i],missCount[i]);}std::puts("]}");b3DestroyPlayer(player);b3DestroyRecording(recording);assert(b3GetWorldCount()==0);}
